create extension if not exists "vector";
create extension if not exists "uuid-ossp";
create extension if not exists "pgcrypto";
create type gov_repo.agent_type as enum ('autonomous','assistive','supervisory','gateway','orchestrator','retrieval','classifier');
create type gov_repo.agent_risk_level as enum ('critical','high','medium','low');
create type gov_repo.ai_act_risk_class as enum ('unacceptable','high','limited','minimal');
create type gov_repo.oversight_level as enum ('l1_automated','l2_human_review','l3_human_approval','l4_human_in_loop');
create type gov_repo.agent_status as enum ('pending_registration','registered','approved','active','suspended','under_review','decommissioned');
create type gov_repo.edge_relationship as enum ('CALLS_AGENT','DELEGATES_TO','SUPERVISES','DEPENDS_ON','ESCALATES_TO','ORCHESTRATES','FALLBACK_TO','PEER_COORDINATES');
create type gov_repo.resource_type as enum ('mcp_server','tool','model','prompt','policy','api','database','file_system','message_queue','vector_store');
create type gov_repo.access_type as enum ('read','write','execute','admin','read_write');
create type gov_repo.propagation_type as enum ('direct','indirect','cascading');
create table gov_repo.agents (
 agent_id uuid primary key default uuid_generate_v4(), agent_code varchar(20) not null, name varchar(255) not null, description text not null, version varchar(50) not null default '1.0.0', ai_system_id uuid, agent_type gov_repo.agent_type not null, risk_level gov_repo.agent_risk_level not null default 'medium', ai_act_risk_class gov_repo.ai_act_risk_class not null default 'minimal', oversight_level gov_repo.oversight_level not null default 'l2_human_review', owner_user_id uuid not null references gov_repo.governance_users(user_id), technical_owner_id uuid references gov_repo.governance_users(user_id), business_domain varchar(100), department varchar(100), model_name varchar(255), model_version varchar(100), model_provider varchar(100), model_is_local boolean not null default false, model_endpoint text, deployment_env varchar(30) not null default 'development' check (deployment_env in ('development','staging','production')), deployment_region varchar(50), deployment_type varchar(30) not null default 'on_premises' check (deployment_type in ('on_premises','private_cloud','hybrid','public_cloud')), status gov_repo.agent_status not null default 'pending_registration', approved_for_production boolean not null default false, suspended_reason text, suspended_at timestamptz, cg_ag_001_registered boolean not null default false, cg_ag_002_owner boolean not null default false, cg_ag_003_model_reg boolean not null default false, cg_ag_007_oversight boolean not null default false, cg_ag_008_audit_trail boolean not null default false, cg_ag_010_classified boolean not null default false, cg_ag_012_autonomous_governed boolean not null default false, conformity_assessment_id uuid references gov_repo.conformity_assessments(assessment_id), eu_ai_db_registered boolean not null default false, eu_ai_db_ref varchar(100), tags jsonb not null default '[]', capabilities jsonb not null default '[]', external_refs jsonb not null default '{}', organisation_id uuid not null references gov_repo.organisations(organisation_id), ledger_entry_seq bigint references gov_repo.governance_ledger(entry_sequence), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid not null references gov_repo.governance_users(user_id), constraint agents_code_org_unique unique(agent_code,organisation_id));
comment on table gov_repo.agents is 'AI Agent master registry. Node principal of the Governance Knowledge Graph. CG-AG-001 (Inventory) | CG-AG-002 (Owner) | CG-AG-010 (Risk Classification). [C2] ai_system_id links agent to its parent AI System (AI Act Art. 3.1). FK to gov_repo.ai_systems added in Migration 006. NULL ai_system_id = governance gap — agent not associated to any AI System. Applicable to any regulated sector: financial services, insurance, healthcare, utilities, public sector, critical infrastructure.';
comment on column gov_repo.agents.ai_system_id is '[C2] AI Act Art. 3(1) defines AI System as the regulated unit, not individual agents. Example: Credit Scoring AI System contains 4 agents (scoring, fraud, risk, explainability). This FK will be enforced in Migration 006 when gov_repo.ai_systems is created.';
comment on column gov_repo.agents.model_is_local is 'Data sovereignty flag. TRUE = model runs on-premises or in private cloud (no data leaves the organisation''s controlled jurisdiction). Required for: agents processing PHI, PII, financial data, or any data subject to residency requirements (GDPR, DORA, NIS2, sector-specific rules). Applicable to: financial services, healthcare, insurance, public sector, critical infrastructure, any organisation with data localisation obligations.';
create index idx_agents_org on gov_repo.agents(organisation_id);
create index idx_agents_status on gov_repo.agents(status);
create index idx_agents_risk_level on gov_repo.agents(risk_level);
create index idx_agents_ai_act on gov_repo.agents(ai_act_risk_class);
create index idx_agents_owner on gov_repo.agents(owner_user_id);
create index idx_agents_type on gov_repo.agents(agent_type);
create index idx_agents_domain on gov_repo.agents(business_domain);
create index idx_agents_ai_system on gov_repo.agents(ai_system_id) where ai_system_id is not null;
create index idx_agents_tags on gov_repo.agents using gin(tags);
create index idx_agents_capabilities on gov_repo.agents using gin(capabilities);
create index idx_agents_no_system on gov_repo.agents(organisation_id) where ai_system_id is null and status='active';
create index idx_agents_cg001_gap on gov_repo.agents(organisation_id) where cg_ag_001_registered=false and status not in ('decommissioned');
create or replace function gov_repo.update_agent_compliance_flags() returns trigger language plpgsql as $$ begin new.cg_ag_001_registered := (new.agent_code is not null and new.name is not null and new.agent_type is not null and new.organisation_id is not null); new.cg_ag_002_owner := (new.owner_user_id is not null); new.cg_ag_003_model_reg := (new.model_name is not null and new.model_provider is not null); new.cg_ag_007_oversight := (new.oversight_level is not null and (new.risk_level='low' or new.oversight_level in ('l2_human_review','l3_human_approval','l4_human_in_loop'))); return new; end; $$;
create trigger trg_agents_compliance_flags before insert or update on gov_repo.agents for each row execute function gov_repo.update_agent_compliance_flags();
create trigger trg_agents_updated_at before update on gov_repo.agents for each row execute function gov_repo.set_updated_at();
alter table gov_repo.agents enable row level security;;
